<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ArrowLeft, BookOpen, Bot, ChevronDown, ChevronRight, Clock3, ExternalLink, FileText, LoaderCircle, MoreHorizontal, PanelRightClose, RotateCcw, Save, StickyNote, Trash2, X } from 'lucide-vue-next'
import { useI18n } from 'vue-i18n'
import mascotIdle from '@/assets/ai-mascot/mascot-idle.png'
import mascotStreaming from '@/assets/ai-mascot/mascot-streaming.gif'
import VuePromptComposer from './VuePromptComposer.vue'
import VueAssistantMarkdown from './VueAssistantMarkdown.vue'
import { useVueAiChat } from '@/composables/useVueAiChat'
import { useZustandSelector } from '@/composables/useZustandSelector'
import { useAppStore } from '@/stores/appStore'
import { useChatStore, type PendingEdit, type RagSource, type TimelineItem } from '@/stores/chatStore'
import { useSettingsStore } from '@/stores/settingsStore'
import { useEditorStore } from '@/stores/editorStore'
import { useReadingArtifactsStore, type ReadingArtifactFilter } from '@/stores/readingArtifactsStore'
import { readRememberedFile } from '@/services/persistedFileAccess'
import { deleteChatSession } from '@/services/database/persistence'
import { isSameFilePath } from '@/services/pathIdentity'
import { toast } from '@/services/toast'
import type { ActionProposal, ChatMessage, ChatMessageContextMeta, ChatMessageSource, LocalChatMessageSource } from '@/services/ai/types'
import { saveAssistantMessageAsMarkdown } from '@/services/assistantMessageExport'
import { applyPendingEditCommand } from '@/services/pendingEditCommand'
import { loadReadingReminders, type ReadingReminder } from '@/services/database/readingReminders'
import { cancelReadingReminder, deleteReadingReminder, editReadingReminderTime, retryReadingReminder } from '@/services/readingReminders'
import { READING_REMINDER_DEVELOPMENT_MESSAGE, READING_REMINDER_FEATURE_AVAILABLE } from '@/services/readingReminderFeature'
import { getAnnotationStructuredContent, getReadingArtifactQuestion, getReadingArtifactReferences, resolveAnnotationPosition, type ReadingArtifact, type ReadingArtifactType } from '@/services/database/readingArtifacts'

const props = defineProps<{ fullscreenDragHandleProps?: { onPointerDown: (event: PointerEvent) => void; onPointerMove: (event: PointerEvent) => void; onPointerUp: (event: PointerEvent) => void; onPointerCancel: (event: PointerEvent) => void } }>()
const { t } = useI18n()
const { messages, streaming, error, timeline, sendMessage, cancelStream } = useVueAiChat()
const hasMoreHistory = useZustandSelector(useChatStore, (state) => state.hasMoreHistory)
const mascotEnabled = useZustandSelector(useSettingsStore, (state) => state.appearance.aiMascotAvatarEnabled)
const artifacts = useZustandSelector(useReadingArtifactsStore, (state) => state.artifacts)
const artifactsLoading = useZustandSelector(useReadingArtifactsStore, (state) => state.loading)
const artifactFilter = useZustandSelector(useReadingArtifactsStore, (state) => state.filter)
const artifactQuery = useZustandSelector(useReadingArtifactsStore, (state) => state.query)
const artifactPage = useZustandSelector(useReadingArtifactsStore, (state) => state.page)
const artifactPageSize = useZustandSelector(useReadingArtifactsStore, (state) => state.pageSize)
const artifactTotal = useZustandSelector(useReadingArtifactsStore, (state) => state.total)
const anchorStatuses = useZustandSelector(useReadingArtifactsStore, (state) => state.anchorStatuses)
const panelView = ref<'chat' | 'artifacts' | 'reminders'>('chat')
const reasoningMode = ref<'off' | 'on'>('off')
const resetManualToggle = ref(0)
const loadingHistory = ref(false)
const reminders = ref<ReadingReminder[]>([])
const remindersLoading = ref(false)
const chatContainer = ref<HTMLElement | null>(null)
const sourceExpanded = ref<Record<string, boolean>>({})
const saveMenu = ref<string | null>(null)
const timelineOpen = ref(false)
const artifactSearch = ref('')
const editingReminder = ref<{ id: string; value: string } | null>(null)
const artifactExpanded = ref<Record<string, boolean>>({})
let artifactSearchTimer: number | undefined
const visibleMessages = computed(() => messages.value.filter((message) => !message.hidden))
const userQuestions = computed(() => new Map(messages.value.filter((message) => message.role === 'user' && message.id).map((message) => [message.id!, (message.displayContent ?? message.content).trim()])))
const totalArtifactPages = computed(() => Math.max(1, Math.ceil(artifactTotal.value / artifactPageSize.value)))
const latestTimelineItem = computed(() => timeline.value[timeline.value.length - 1])
const ARTIFACT_TYPES: Array<{ value: ReadingArtifactFilter; label: string }> = [{ value: 'all', label: t('aiPanel.filterAll') }, { value: 'summary', label: t('aiPanel.filterSummary') }, { value: 'question_set', label: t('aiPanel.filterQuestionSet') }, { value: 'annotation', label: t('aiPanel.filterAnnotation') }, { value: 'note', label: t('aiPanel.filterNote') }]
const TYPE_LABEL: Record<ReadingArtifactType, string> = { summary: t('aiPanel.artifactTypeSummary'), question_set: t('aiPanel.artifactTypeQuestionSet'), annotation: t('aiPanel.artifactTypeAnnotation'), note: t('aiPanel.artifactTypeNote') }

function sourceHeading(source: LocalChatMessageSource): string { return source.titlePath?.length ? source.titlePath.join(' / ') : source.heading || '' }
function artifactTitle(type: ReadingArtifactType, content: string): string { const first = content.split('\n').map((line) => line.replace(/^#+\s*/, '').trim()).find(Boolean) || TYPE_LABEL[type]; return first.length > 40 ? `${first.slice(0, 40)}…` : first }
function formatDate(value: number): string { return new Date(value).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) }
function isWeb(source: ChatMessageSource): boolean { return source.kind === 'web' }
function sourceUrl(source: ChatMessageSource): string { return source.kind === 'web' ? source.url : '' }
function sourceTitle(source: ChatMessageSource): string { return source.kind === 'web' ? source.title : '' }
function sourceLabel(source: ChatMessageSource): string { return source.kind === 'web' ? source.title : t('aiPanel.sourceFileLine', { file: source.fileName, start: source.startLine, end: source.endLine }) }
function openMessageSource(source: ChatMessageSource): void { if (source.kind !== 'web') void openSource(source) }
function artifactReferenceUrl(reference: ReturnType<typeof getReadingArtifactReferences>[number]): string { return reference.kind === 'web' ? reference.url : '' }
function artifactReferenceTitle(reference: ReturnType<typeof getReadingArtifactReferences>[number]): string { return reference.kind === 'web' ? reference.title : '' }
function artifactReferenceLabel(reference: ReturnType<typeof getReadingArtifactReferences>[number]): string { return reference.kind === 'web' ? reference.title : `${reference.fileName} · L${reference.startLine}-${reference.endLine}` }
function openArtifactReference(reference: ReturnType<typeof getReadingArtifactReferences>[number]): void { if (reference.kind !== 'web') void openSource(reference) }
function messageKey(message: ChatMessage, index: number): string { return message.id || `${message.role}-${index}` }
function iconTone(type: TimelineItem['type']): string { return ({ index_initializing: 'primary', index_ready: 'success', index_fallback: 'warning', local_search_start: 'primary', local_search_found: 'success', local_search_empty: 'muted', web_search_start: 'warning', web_search_done: 'success', answer_streaming: 'primary', done: 'success', error: 'error' } as const)[type] }
function artifactSource(artifact: ReadingArtifact): string { const source = artifact.source; return source?.fileName ? [source.fileName, source.headingPath?.join(' / '), source.startLine ? `L${source.startLine}-${source.endLine}` : ''].filter(Boolean).join(' · ') : '' }
function reminderValue(reminder: ReadingReminder): string { const date = new Date(reminder.dueAtUtc); const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000); return local.toISOString().slice(0, 16) }

function scrollToBottom(): void { requestAnimationFrame(() => chatContainer.value?.scrollTo({ top: chatContainer.value.scrollHeight, behavior: 'auto' })) }
function closePanel(): void { useAppStore.getState().toggleAiPanel() }
async function loadHistory(): Promise<void> { loadingHistory.value = true; try { await useChatStore.getState().loadMoreHistory() } finally { loadingHistory.value = false } }
function send(): void { const state = useChatStore.getState(); if ((!state.draftInput.trim() && !state.contextTags.length) || state.streaming) return; void sendMessage(state.draftInput, undefined, state.contextTags.length ? state.contextTags : undefined, undefined, reasoningMode.value); state.setDraftInput(''); state.clearContextTags(); reasoningMode.value = 'off'; resetManualToggle.value += 1; scrollToBottom() }
function retry(): void { for (let index = visibleMessages.value.length - 1; index >= 0; index -= 1) { const message = visibleMessages.value[index]; if (message.role === 'user') { useChatStore.getState().removeLastMessage(); useChatStore.getState().setError(null); void sendMessage(message.content); return } } }
async function openSource(source: Pick<RagSource, 'filePath' | 'startLine' | 'endLine'>): Promise<void> { try { const editor = useEditorStore.getState(); const existing = editor.tabs.find((tab) => isSameFilePath(tab.filePath, source.filePath)); let tabId = existing?.id; if (!tabId) { const content = await readRememberedFile(source.filePath); editor.addTab(source.filePath, source.filePath.split(/[/\\]/).pop() || source.filePath, content); tabId = useEditorStore.getState().activeTabId || undefined } else editor.setActiveTab(tabId); if (!tabId) return; editor.setViewMode('edit'); editor.requestReveal(tabId, source.startLine, source.endLine) } catch (cause) { toast.error(cause instanceof Error ? cause.message : t('aiPanel.openSourceFailed')) } }
async function openArtifactSource(artifact: ReadingArtifact): Promise<void> { const source = artifact.source; if (!source?.filePath) { toast.error(t('aiPanel.artifactNoSource')); return }; try { const editor = useEditorStore.getState(); const existing = editor.tabs.find((tab) => isSameFilePath(tab.filePath, source.filePath)); let tabId = existing?.id; let content = existing?.content ?? ''; if (!tabId) { content = await readRememberedFile(source.filePath); editor.addTab(source.filePath, source.filePath.split(/[/\\]/).pop() || source.filePath, content); tabId = useEditorStore.getState().activeTabId || undefined } else editor.setActiveTab(tabId); if (!tabId) return; editor.setViewMode('edit'); let start = source.startLine; let end = source.endLine; if (artifact.type === 'annotation') { const annotation = getAnnotationStructuredContent(artifact); const position = annotation ? resolveAnnotationPosition(content, annotation, source) : null; start = position?.startLine ?? start; end = position?.endLine ?? end } if (start && end) editor.requestReveal(tabId, start, end) } catch (cause) { toast.error(cause instanceof Error ? cause.message : t('aiPanel.openSourceFailed')) } }
async function saveMarkdown(content: string, sources?: ChatMessageSource[], question?: string): Promise<void> { await saveAssistantMessageAsMarkdown(content, sources, question) }
async function saveArtifact(type: ReadingArtifactType, content: string, sources: ChatMessageSource[] | undefined, contextMeta: ChatMessageContextMeta | undefined, messageId: string | undefined, question: string | undefined): Promise<void> { const trimmed = content.trim(); if (!trimmed) return; const source = sources?.find((item): item is LocalChatMessageSource => item.kind !== 'web'); const payload = type === 'annotation' && source ? { type, title: (source.heading || sourceHeading(source) || source.fileName).slice(0, 40), content: trimmed, sources, contextScope: contextMeta?.readingScope, messageId, question, structuredContent: { quote: source.heading || sourceHeading(source) || `${source.fileName} L${source.startLine}-${source.endLine}`, note: trimmed } } : { type, title: artifactTitle(type, trimmed), content: trimmed, sources, contextScope: contextMeta?.readingScope, messageId, question }; if (type === 'annotation' && !source) { toast.error(t('aiPanel.annotationNeedsSource')); return } try { const saved = await useReadingArtifactsStore.getState().saveArtifactFromMessage(payload); saved ? toast.success(t('aiPanel.savedAs', { type: TYPE_LABEL[type] })) : toast.error(t('aiPanel.saveArtifactFailed')) } catch (cause) { toast.error(cause instanceof Error ? cause.message : t('aiPanel.saveArtifactFailed')) } }
async function deleteSession(sessionId: string): Promise<void> { if (!window.confirm(t('aiPanel.deleteSessionConfirm'))) return; try { await deleteChatSession(sessionId); useChatStore.getState().removeSessionMessages(sessionId); toast.success(t('aiPanel.sessionDeleted')) } catch (cause) { toast.error(cause instanceof Error ? cause.message : t('aiPanel.deleteSessionFailed')) } }
function deleteArtifact(id: string): void { if (window.confirm(t('aiPanel.deleteArtifactConfirm'))) void useReadingArtifactsStore.getState().deleteArtifact(id) }
async function refreshReminders(): Promise<void> { remindersLoading.value = true; try { reminders.value = await loadReadingReminders() } catch (cause) { toast.error(cause instanceof Error ? cause.message : t('aiPanel.loadRemindersFailed')) } finally { remindersLoading.value = false } }
async function reminderAction(action: 'cancel' | 'retry' | 'delete', id: string): Promise<void> { try { if (action === 'cancel') await cancelReadingReminder(id); if (action === 'retry') await retryReadingReminder(id); if (action === 'delete') await deleteReadingReminder(id); await refreshReminders() } catch (cause) { toast.error(cause instanceof Error ? cause.message : t('aiPanel.reminderActionFailed')) } }
async function saveReminder(): Promise<void> { const edit = editingReminder.value; if (!edit) return; const timestamp = new Date(edit.value).getTime(); if (!Number.isFinite(timestamp)) return; try { await editReadingReminderTime(edit.id, timestamp, Intl.DateTimeFormat().resolvedOptions().timeZone); editingReminder.value = null; await refreshReminders() } catch (cause) { toast.error(cause instanceof Error ? cause.message : t('aiPanel.editReminderFailed')) } }
function applyProposal(id: string, accepted: boolean): void { void import('@/services/actionProposalCommand').then(({ confirmActionProposalCommand, rejectActionProposalCommand }) => accepted ? confirmActionProposalCommand(id) : rejectActionProposalCommand(id)) }
function applyEdit(id: string): void { applyPendingEditCommand(id) }

watch([messages, streaming], () => { if (panelView.value === 'chat') scrollToBottom() }, { deep: false })
watch(panelView, (view) => { if (view === 'artifacts') void useReadingArtifactsStore.getState().loadArtifacts(); if (view === 'reminders' && READING_REMINDER_FEATURE_AVAILABLE) void refreshReminders(); if (view === 'chat') scrollToBottom() })
watch([artifactFilter, artifactQuery, artifactPage], () => { if (panelView.value === 'artifacts') void useReadingArtifactsStore.getState().loadArtifacts() })
watch(artifactSearch, (query) => { if (artifactSearchTimer) window.clearTimeout(artifactSearchTimer); artifactSearchTimer = window.setTimeout(() => useReadingArtifactsStore.getState().setQuery(query), 180) })
function onShortcut(): void { send() }
onMounted(() => { window.addEventListener('guanmo:submit-ai-shortcut', onShortcut); if (useChatStore.getState().draftInput.trim() && useSettingsStore.getState().editor.autoSendAiShortcut) window.setTimeout(onShortcut, 100) })
onBeforeUnmount(() => { window.removeEventListener('guanmo:submit-ai-shortcut', onShortcut); if (artifactSearchTimer) window.clearTimeout(artifactSearchTimer) })
</script>

<template>
  <section class="gm-vue-ai-panel">
    <header class="gm-vue-ai-panel__header" :class="{ 'gm-vue-ai-panel__header--draggable': fullscreenDragHandleProps }" v-on="fullscreenDragHandleProps ? { pointerdown: fullscreenDragHandleProps.onPointerDown, pointermove: fullscreenDragHandleProps.onPointerMove, pointerup: fullscreenDragHandleProps.onPointerUp, pointercancel: fullscreenDragHandleProps.onPointerCancel } : {}">
      <div><strong>AI</strong><span v-if="streaming">{{ t('aiPanel.generating') }}</span></div><nav @pointerdown.stop><button type="button" :data-active="panelView === 'artifacts'" title="Reading artifacts" @click="panelView = 'artifacts'"><BookOpen :size="16" aria-hidden="true" /></button><button type="button" :data-active="panelView === 'reminders'" title="Reading reminders" @click="panelView = 'reminders'"><Clock3 :size="16" aria-hidden="true" /></button><button v-if="panelView === 'chat' && messages.length" type="button" :title="t('aiPanel.clear')" @click="useChatStore.getState().clearMessages()"><Trash2 :size="16" aria-hidden="true" /></button><button v-if="panelView !== 'chat'" type="button" :title="t('aiPanel.back')" @click="panelView = 'chat'"><ArrowLeft :size="16" aria-hidden="true" /></button><button type="button" :title="t('common.close')" @click="closePanel"><PanelRightClose :size="16" aria-hidden="true" /></button></nav>
    </header>
    <div v-if="timeline.length" class="gm-vue-ai-panel__timeline"><button type="button" @click="timelineOpen = !timelineOpen"><ChevronRight :size="13" :class="{ 'gm-vue-ai-panel__rotate': timelineOpen }" aria-hidden="true" /><span v-if="!timelineOpen">{{ latestTimelineItem?.label }}</span><span v-else>{{ t('aiPanel.agent') }}</span><i :data-tone="iconTone(latestTimelineItem?.type || 'done')"></i></button><ol v-if="timelineOpen"><li v-for="item in timeline" :key="item.id"><i :data-tone="iconTone(item.type)"></i><span><b>{{ item.label }}</b><small v-if="item.detail">{{ item.detail }}</small></span><time>{{ new Date(item.timestamp).toLocaleTimeString() }}</time></li></ol></div>
    <main ref="chatContainer" class="gm-vue-ai-panel__body">
      <section v-if="panelView === 'artifacts'" class="gm-vue-ai-panel__artifacts"><div class="gm-vue-ai-panel__view-title"><h2>{{ t('aiPanel.readingArtifacts') }}</h2><span>{{ t('aiPanel.artifactCount', { count: artifactTotal }) }}</span></div><input v-model="artifactSearch" type="search" :placeholder="t('aiPanel.searchArtifacts')" /><div class="gm-vue-ai-panel__filters"><button v-for="option in ARTIFACT_TYPES" :key="option.value" type="button" :data-active="artifactFilter === option.value" @click="useReadingArtifactsStore.getState().setFilter(option.value)">{{ option.label }}</button></div><p v-if="artifactsLoading && !artifacts.length" class="gm-vue-ai-panel__empty">{{ t('aiPanel.loading') }}</p><p v-else-if="!artifacts.length" class="gm-vue-ai-panel__empty">{{ t('aiPanel.noArtifacts') }}</p><article v-for="artifact in artifacts" :key="artifact.id" class="gm-vue-ai-artifact"><button type="button" class="gm-vue-ai-artifact__summary" :aria-expanded="artifactExpanded[artifact.id]" @click="artifactExpanded[artifact.id] = !artifactExpanded[artifact.id]"><em>{{ TYPE_LABEL[artifact.type] }}</em><b>{{ artifact.title }}</b><ChevronDown :size="15" :class="{ 'gm-vue-ai-panel__rotate': artifactExpanded[artifact.id] }" aria-hidden="true" /></button><p v-if="artifactSource(artifact)" class="gm-vue-ai-artifact__source">{{ artifactSource(artifact) }}</p><div v-if="artifactExpanded[artifact.id]" class="gm-vue-ai-artifact__content"><div v-if="getReadingArtifactQuestion(artifact)" class="gm-vue-ai-artifact__question"><b>{{ t('aiPanel.originalQuestion') }}</b><p>{{ getReadingArtifactQuestion(artifact) }}</p></div><div v-if="getAnnotationStructuredContent(artifact)" class="gm-vue-ai-artifact__annotation"><b>{{ t('aiPanel.quotedText') }}</b><blockquote>{{ getAnnotationStructuredContent(artifact)?.quote }}</blockquote><VueAssistantMarkdown :content="getAnnotationStructuredContent(artifact)?.note || artifact.content" compact /></div><VueAssistantMarkdown v-else :content="artifact.content" compact /><div v-if="getReadingArtifactReferences(artifact).length" class="gm-vue-ai-artifact__references"><b>{{ t('aiPanel.references') }}</b><template v-for="(reference, index) in getReadingArtifactReferences(artifact)" :key="index"><a v-if="reference.kind === 'web'" :href="artifactReferenceUrl(reference)" target="_blank" rel="noreferrer">{{ artifactReferenceTitle(reference) }}</a><button v-else type="button" @click="openArtifactReference(reference)">{{ artifactReferenceLabel(reference) }}</button></template></div></div><footer><button v-if="artifact.source?.filePath" type="button" @click="openArtifactSource(artifact)">{{ t('aiPanel.openSource') }}</button><button type="button" @click="deleteArtifact(artifact.id)">{{ t('aiPanel.delete') }}</button><time>{{ new Date(artifact.createdAt).toLocaleDateString('zh-CN') }}</time></footer></article><footer v-if="artifactTotal"><span>{{ t('aiPanel.pageInfo', { page: artifactPage, pages: totalArtifactPages }) }}</span><button type="button" :disabled="artifactPage <= 1" @click="useReadingArtifactsStore.getState().setPage(artifactPage - 1)">{{ t('aiPanel.previousPage') }}</button><button type="button" :disabled="artifactPage >= totalArtifactPages" @click="useReadingArtifactsStore.getState().setPage(artifactPage + 1)">{{ t('aiPanel.nextPage') }}</button></footer></section>
      <section v-else-if="panelView === 'reminders'" class="gm-vue-ai-panel__reminders"><template v-if="!READING_REMINDER_FEATURE_AVAILABLE"><p class="gm-vue-ai-panel__empty">{{ READING_REMINDER_DEVELOPMENT_MESSAGE }}</p></template><template v-else><p v-if="remindersLoading" class="gm-vue-ai-panel__empty">{{ t('aiPanel.loadingReminders') }}</p><p v-else-if="!reminders.length" class="gm-vue-ai-panel__empty">{{ t('aiPanel.noReminders') }}</p><article v-for="reminder in reminders" :key="reminder.id"><b>{{ reminder.title || t('aiPanel.reminderTitle') }}</b><p>{{ new Date(reminder.dueAtUtc).toLocaleString('zh-CN') }} · {{ reminder.status }}</p><input v-if="editingReminder?.id === reminder.id" v-model="editingReminder.value" type="datetime-local" /><footer><button type="button" @click="editingReminder = { id: reminder.id, value: reminderValue(reminder) }">{{ t('aiPanel.edit') }}</button><button v-if="editingReminder?.id === reminder.id" type="button" @click="saveReminder">{{ t('aiPanel.save') }}</button><button type="button" @click="reminderAction('cancel', reminder.id)">{{ t('aiPanel.cancel') }}</button><button v-if="reminder.status === 'failed'" type="button" @click="reminderAction('retry', reminder.id)">{{ t('aiPanel.retry') }}</button><button type="button" @click="reminderAction('delete', reminder.id)">{{ t('aiPanel.delete') }}</button></footer></article></template></section>
      <section v-else class="gm-vue-ai-panel__chat"><div v-if="!visibleMessages.length" class="gm-vue-ai-panel__empty"><button v-if="hasMoreHistory" type="button" :disabled="loadingHistory" @click="loadHistory">{{ loadingHistory ? t('aiPanel.loading') : t('aiPanel.loadHistory') }}</button><div class="gm-vue-ai-panel__avatar gm-vue-ai-panel__avatar--empty"><img v-if="mascotEnabled" :src="mascotIdle" alt="AI" /><Bot v-else :size="34" aria-hidden="true" /></div><b>{{ t('aiPanel.start') }}</b><p>{{ t('aiPanel.startDescription') }}</p></div><div v-else class="gm-vue-ai-panel__messages"><button v-if="hasMoreHistory" type="button" class="gm-vue-ai-panel__history" :disabled="loadingHistory" @click="loadHistory">{{ loadingHistory ? t('aiPanel.loading') : t('aiPanel.loadOlder') }}</button><template v-for="(message, index) in visibleMessages" :key="messageKey(message, index)"><div v-if="message.sessionId && message.sessionId !== visibleMessages[index - 1]?.sessionId" class="gm-vue-ai-panel__divider"><span>{{ message.sessionTitle || t('aiPanel.historyDivider') }} · {{ message.timestamp ? formatDate(message.timestamp) : '' }}</span><button type="button" @click="message.sessionId && deleteSession(message.sessionId)">{{ t('aiPanel.delete') }}</button></div><div v-else-if="!message.sessionId && visibleMessages[index - 1]?.sessionId" class="gm-vue-ai-panel__divider"><span>{{ t('aiPanel.aboveIsHistory') }}</span></div><article class="gm-vue-ai-message" :class="`gm-vue-ai-message--${message.role}`" :data-chat-streaming="message.role === 'assistant' && index === visibleMessages.length - 1 && streaming ? 'true' : undefined"><div v-if="message.role === 'assistant'" class="gm-vue-ai-panel__avatar"><img v-if="mascotEnabled" :src="streaming && index === visibleMessages.length - 1 ? mascotStreaming : mascotIdle" alt="AI" /><Bot v-else :size="18" aria-hidden="true" /></div><div class="gm-vue-ai-message__content"><VueAssistantMarkdown :content="message.displayContent ?? message.content" /><div v-if="message.tags?.length" class="gm-vue-ai-message__tags"><span v-for="(tag, tagIndex) in message.tags" :key="tagIndex"><FileText :size="11" aria-hidden="true" />{{ tag.title }}</span></div><div v-if="message.sources?.length" class="gm-vue-ai-message__sources"><button type="button" @click="sourceExpanded[messageKey(message, index)] = !sourceExpanded[messageKey(message, index)]">{{ t('aiPanel.sources', { count: message.sources.length }) }}<ChevronRight :size="12" :class="{ 'gm-vue-ai-panel__rotate': sourceExpanded[messageKey(message, index)] }" aria-hidden="true" /></button><div v-if="sourceExpanded[messageKey(message, index)]"><template v-for="(source, sourceIndex) in message.sources" :key="sourceIndex"><a v-if="source.kind === 'web'" :href="sourceUrl(source)" target="_blank" rel="noreferrer"><ExternalLink :size="12" aria-hidden="true" />{{ sourceTitle(source) }}</a><button v-else type="button" @click="openMessageSource(source)">{{ sourceLabel(source) }}</button></template></div></div><div v-if="message.role === 'assistant' && !streaming && (message.displayContent ?? message.content).trim()" class="gm-vue-ai-message__actions"><button type="button" title="Save answer" @click="saveMarkdown(message.displayContent ?? message.content, message.sources, message.parentId ? userQuestions.get(message.parentId) : undefined)"><Save :size="13" aria-hidden="true" /></button><button type="button" title="Save reading artifact" @click="saveMenu = saveMenu === messageKey(message, index) ? null : messageKey(message, index)"><MoreHorizontal :size="14" aria-hidden="true" /></button><div v-if="saveMenu === messageKey(message, index)" class="gm-vue-ai-message__save-menu"><button v-for="type in (['summary', 'question_set', 'note'] as ReadingArtifactType[])" :key="type" type="button" @click="saveArtifact(type, message.displayContent ?? message.content, message.sources, message.contextMeta, message.id, message.parentId ? userQuestions.get(message.parentId) : undefined); saveMenu = null">{